/* From Uiverse.io by Tsiangana  - Tags: simple, card, modern, color, card hover */
.__UIV_SCOPE__ .card {
  width: 320px;
  height: 220px;
  perspective: 1000px;
  background: #fff;
  border-radius: 10px;
  box-shadow: 1px 1px 20px #c7c7c7;
}

.__UIV_SCOPE__ .card .paleta {
  width: 100%;
  height: 180px;
  position: absolute;
  bottom: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .component {
  height: 23px;
}

.__UIV_SCOPE__ .card .paleta .cores {
  width: 80px;
  height: 180px;
  cursor: pointer;
  transition: 0.3s linear;
  overflow: hidden;
}
.__UIV_SCOPE__ .card .paleta .cores:hover {
  width: 120px;
  transition: 0.4s linear;
}

.__UIV_SCOPE__ .circle {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background-color: #fff;
  position: absolute;
  top: -60px;
  box-shadow: 1px 1px 8px #c7c7c7;
  display: flex;
  align-items: center;
  justify-content: center;
}
.__UIV_SCOPE__ .card .paleta .cor1 {
  background-color: #0e3746;
  border-radius: 0px 0px 0px 10px;
}
.__UIV_SCOPE__ .card .paleta .cor2 {
  background-color: #eae8dc;
}
.__UIV_SCOPE__ .card .paleta .cor3 {
  background-color: #f4f2ec;
}
.__UIV_SCOPE__ .card .paleta .cor4 {
  background-color: #be2623;
  border-radius: 0px 0px 10px 0px;
}

.__UIV_SCOPE__ .card .paleta .cores .nome {
  width: 100%;
  height: 30px;
  background-color: #fff;
  text-align: center;
  font-size: 11px;
  font-family: Roboto, sans-serif;
  font-weight: 550;
}

.__UIV_SCOPE__ .card .paleta .func {
  width: 100px;
  display: block;
  transform: rotate(-90deg);
  position: absolute;
  bottom: 40px;
  margin-left: -41px;
  padding-left: 5px;
  color: #fff;
  font-size: 15px;
  font-family: sans-serif;
  font-weight: 500;
}

.__UIV_SCOPE__ .div1 {
  cursor: pointer;
  transition: background-color 0.3s;
  position: absolute;
  bottom: 0;
  width: 80px;
  height: 150px;
}

.__UIV_SCOPE__ .div2 {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background-color: #fff;
  position: absolute;
  top: -60px;
  left: 135px;
  box-shadow: 1px 1px 8px #c7c7c7;
  align-items: center;
  justify-content: center;
  display: none;
}

.__UIV_SCOPE__ .div1:hover + .div2 {
  background-color: #0e3746;
  display: flex;
  color: #fff;
  animation: cssAnimation_0 1512ms 1 ease-out;
}

